type ButtonProps = {
  label: string;
  onClick: (id: number) => void;
  disabled?: boolean;
};

function Button({ label, onClick, disabled = false }: ButtonProps) {
  return (
    <button disabled={disabled} onClick={() => onClick(1)}>
      {label}
    </button>
  );
}

