import { useState } from 'react';

// TODO: define Quest type

// TODO: define QuestCardProps type
function QuestCard({ quest, onComplete }) {
  return (
    <div className={quest.completed ? 'done' : ''}>
      <h3>{quest.title}</h3>
      <span>{quest.xp} XP</span>
      {!quest.completed && (
        <button onClick={() => onComplete(quest.id)}>Complete</button>
      )}
    </div>
  );
}

// TODO: define QuestListProps type
function QuestList({ quests, onComplete }) {
  return (
    <ul>
      {quests.map(q => <QuestCard key={q.id} quest={q} onComplete={onComplete} />)}
    </ul>
  );
}

export default function App() {
  // TODO: type the quests state
  const [quests, setQuests] = useState([
    { id: 1, title: 'Learn TypeScript', xp: 100, completed: false },
    { id: 2, title: 'Type your props', xp: 150, completed: false },
  ]);

  // TODO: type the id parameter
  function handleComplete(id) {
    setQuests(prev => prev.map(q => q.id === id ? { ...q, completed: true } : q));
  }

  return <QuestList quests={quests} onComplete={handleComplete} />;
}
